# Hısnü'l-Müslim — bütün bölümler (1. kısım). (Arapça, Türkçe, sayı, kaynak, not)
K1 = [
('🌅 Uyku ve uyanma', [
 ('Uykudan uyanınca', [
  ('الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ','Bizi öldürdükten (uyuttuktan) sonra dirilten Allah’a hamd olsun. Dönüş O’nadır.',1,'Buhârî, Daavât 7 (nr. 6312)',''),
  ('لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ، سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَٰهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ، رَبِّ اغْفِرْ لِي','Allah’tan başka ilâh yoktur; O tektir, ortağı yoktur. Mülk O’nundur, hamd O’nadır; O her şeye kadirdir. Allah noksanlıklardan uzaktır, hamd Allah’adır, Allah’tan başka ilâh yoktur, Allah en büyüktür. Güç ve kuvvet ancak yüce ve büyük Allah’ındır. Rabbim, beni bağışla.',1,'Buhârî, Teheccüd 21 (nr. 1154)','Gece uyanıp bunu söyleyen ve dua edenin duası kabul olunur; abdest alıp namaz kılarsa namazı kabul edilir.'),
  ('الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لِي بِذِكْرِهِ','Bedenime âfiyet veren, ruhumu bana geri döndüren ve kendisini anmama izin veren Allah’a hamd olsun.',1,'Tirmizî, Daavât 20 (nr. 3401)',''),
 ]),
 ('Yatağa girerken', [
  ('قُلْ هُوَ اللَّهُ أَحَدٌ … قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ … قُلْ أَعُوذُ بِرَبِّ النَّاسِ …','Avuçlar birleştirilir, İhlâs, Felak ve Nâs okunup avuçlara üflenir; eller baştan, yüzden ve vücudun önünden başlanarak gücün yettiği yere sürülür.',3,'Buhârî, Fezâilü’l-Kur’ân 14 (nr. 5017)','Resûlullah her gece yatağına girince böyle yapardı.'),
  ('اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ … (آيَةُ الْكُرْسِيِّ)','Yatarken Âyetü’l-Kürsî okunur (Bakara 2/255).',1,'Buhârî, Vekâle 10 (nr. 2311)','Okuyana sabaha kadar Allah’tan bir koruyucu olur, şeytan ona yaklaşamaz.'),
  ('آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ … (خَوَاتِيمُ سُورَةِ الْبَقَرَةِ)','Bakara sûresinin son iki âyeti (2/285-286) okunur.',1,'Buhârî, Fezâilü’l-Kur’ân 10 (nr. 5009); Müslim, Müsâfirîn 255 (nr. 807)','Geceleyin okuyana bu iki âyet yeter.'),
  ('بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ','Rabbim! Senin adınla yanımı yere koydum, senin adınla kaldırırım. Eğer ruhumu tutarsan ona merhamet et; salıverirsen salih kullarını koruduğun şeyle onu koru.',1,'Buhârî, Daavât 13 (nr. 6320); Müslim, Zikir 64 (nr. 2714)','Yatağına gelen, yatağını elbisesinin ucuyla üç kez silkeler, sonra bunu söyler.'),
  ('اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ','Allahım! Kullarını dirilteceğin gün beni azabından koru.',3,'Ebû Dâvûd, Edeb 107 (nr. 5045); Tirmizî, Daavât 18 (nr. 3398)','Resûlullah uyumak isteyince sağ elini yanağının altına koyar, bunu söylerdi.'),
  ('بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا','Allahım! Senin adınla ölür (uyur) ve dirilirim.',1,'Buhârî, Daavât 7 (nr. 6324)',''),
  ('سُبْحَانَ اللَّهِ (٣٣)، الْحَمْدُ لِلَّهِ (٣٣)، اللَّهُ أَكْبَرُ (٣٤)','Otuz üç kez Sübhânallah, otuz üç kez Elhamdülillah, otuz dört kez Allâhu ekber.',1,'Buhârî, Fezâilü’s-sahâbe 9 (nr. 3705); Müslim, Zikir 80 (nr. 2727)','Hz. Fâtıma hizmetçi isteyince Resûlullah bunu öğretti: “Bu sizin için bir hizmetçiden daha hayırlıdır.”'),
  ('اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ','Allahım! Kendimi sana teslim ettim, işimi sana bıraktım, yüzümü sana çevirdim, sırtımı sana dayadım; seni umarak ve senden korkarak. Senden kaçıp sığınılacak yer yine ancak sensin. İndirdiğin kitabına ve gönderdiğin peygamberine iman ettim.',1,'Buhârî, Daavât 6 (nr. 6313); Müslim, Zikir 56 (nr. 2710)','Bunu söyleyip o gece ölen fıtrat üzere ölür. Sözlerinin sonuncusu bu olsun.'),
  ('الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ','Bizi yediren, içiren, ihtiyacımızı gideren ve barındıran Allah’a hamd olsun. Nice kimse var ki ne ihtiyacını giderecek ne de onu barındıracak kimsesi vardır.',1,'Müslim, Zikir 64 (nr. 2715)',''),
  ('اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ','Allahım! Ey gaybı ve görüneni bilen, gökleri ve yeri yaratan, her şeyin Rabbi ve sahibi! Senden başka ilâh olmadığına şahitlik ederim. Nefsimin şerrinden, şeytanın şerrinden ve şirkinden sana sığınırım.',1,'Tirmizî, Daavât 14 (nr. 3392); Ebû Dâvûd, Edeb 107 (nr. 5083)','Sabah, akşam ve yatağa girerken söylenir.'),
 ]),
 ('Gece yatakta dönerken', [
  ('لَا إِلَٰهَ إِلَّا اللَّهُ الْوَاحِدُ الْقَهَّارُ، رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا، الْعَزِيزُ الْغَفَّارُ','Bir ve kahhâr olan; göklerin, yerin ve aralarındakilerin Rabbi, azîz ve gaffâr olan Allah’tan başka ilâh yoktur.',1,'Hâkim, el-Müstedrek, I, 540; Nesâî, Amelü’l-yevm ve’l-leyle, nr. 864',''),
 ]),
 ('Uykuda korkunca, kötü rüya görünce', [
  ('أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ','Allah’ın gazabından, cezasından, kullarının şerrinden, şeytanların kışkırtmalarından ve onların yanıma gelmesinden Allah’ın eksiksiz kelimelerine sığınırım.',1,'Ebû Dâvûd, Tıb 19 (nr. 3893); Tirmizî, Daavât 93 (nr. 3528)',''),
  ('أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ وَمِنْ شَرِّ هَٰذِهِ الرُّؤْيَا','Kovulmuş şeytandan ve bu rüyanın şerrinden Allah’a sığınırım.',3,'Müslim, Rü’yâ 1-5 (nr. 2261-2263)','Kötü rüya gören soluna hafifçe üç kez tükürür, şeytandan ve rüyanın şerrinden Allah’a üç kez sığınır, kimseye anlatmaz, yattığı yanı değiştirir; isterse kalkıp namaz kılar. Güzel rüya Allah’tandır; ona hamd eder ve sevdiğine anlatır.'),
 ]),
 ('Gece namaza kalkınca (teheccüd)', [
  ('اللَّهُمَّ لَكَ الْحَمْدُ، أَنْتَ قَيِّمُ السَّمَاوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ، أَنْتَ نُورُ السَّمَاوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ، أَنْتَ مَلِكُ السَّمَاوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ، أَنْتَ الْحَقُّ، وَوَعْدُكَ الْحَقُّ، وَلِقَاؤُكَ حَقٌّ، وَقَوْلُكَ حَقٌّ، وَالْجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالنَّبِيُّونَ حَقٌّ، وَمُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَقٌّ، وَالسَّاعَةُ حَقٌّ، اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، وَإِلَيْكَ حَاكَمْتُ، فَاغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، لَا إِلَٰهَ إِلَّا أَنْتَ','Allahım! Hamd sana mahsustur; sen göklerin, yerin ve onlarda bulunanların ayakta tutucususun. Hamd sanadır; sen göklerin, yerin ve onlarda bulunanların nurusun. Hamd sanadır; sen göklerin, yerin ve onlarda bulunanların hükümdarısın. Hamd sanadır; sen haksın, vaadin haktır, sana kavuşmak haktır, sözün haktır, cennet haktır, cehennem haktır, peygamberler haktır, Muhammed (s.a.v.) haktır, kıyamet haktır. Allahım! Sana teslim oldum, sana iman ettim, sana tevekkül ettim, sana yöneldim; senin adınla mücadele ettim, sana muhakeme oldum. Önce ve sonra yaptıklarımı, gizlediğimi ve açığa vurduğumu bağışla. Öne alan da sensin, geri bırakan da. Senden başka ilâh yoktur.',1,'Buhârî, Teheccüd 1 (nr. 1120); Müslim, Müsâfirîn 199 (nr. 769)','Resûlullah gece teheccüde kalkınca bunu okurdu.'),
 ]),
]),
('👕 Giyinme, temizlik, ev', [
 ('Elbise giyerken', [
  ('الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَٰذَا الثَّوْبَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ','Benim hiçbir gücüm ve kuvvetim olmadan bana bu elbiseyi giydiren ve onu bana rızık olarak veren Allah’a hamd olsun.',1,'Ebû Dâvûd, Libâs 1 (nr. 4023); Tirmizî, Daavât 56 (nr. 3458)','Bunu söyleyenin geçmiş günahları bağışlanır.'),
 ]),
 ('Yeni elbise giyerken', [
  ('اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ','Allahım! Hamd sanadır; onu bana sen giydirdin. Onun hayrını ve yapıldığı şeyin hayrını senden isterim; onun şerrinden ve yapıldığı şeyin şerrinden sana sığınırım.',1,'Ebû Dâvûd, Libâs 1 (nr. 4020); Tirmizî, Libâs 29 (nr. 1767)',''),
 ]),
 ('Yeni elbise giyene söylenen', [
  ('تُبْلِي وَيُخْلِفُ اللَّهُ تَعَالَىٰ','Eskitesin; Allah yerine yenisini versin.',1,'Ebû Dâvûd, Libâs 1 (nr. 4020)',''),
  ('الْبَسْ جَدِيدًا، وَعِشْ حَمِيدًا، وَمُتْ شَهِيدًا','Yeni giy, övülmüş olarak yaşa, şehit olarak öl.',1,'İbn Mâce, Libâs 2 (nr. 3558)','Resûlullah bunu Hz. Ömer’e söyledi.'),
 ]),
 ('Elbise çıkarırken', [
  ('بِسْمِ اللَّهِ','Allah’ın adıyla.',1,'Tirmizî, Cum‘a 72 (nr. 606)','İnsan elbisesini çıkarırken “Bismillah” derse, cinlerin gözleri ile avret yeri arasında perde olur.'),
 ]),
 ('Tuvalete girerken ve çıkarken', [
  ('بِسْمِ اللَّهِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ','Allah’ın adıyla. Allahım! Erkek ve dişi şeytanlardan (her türlü pislik ve kötülükten) sana sığınırım.',1,'Buhârî, Vudû 9 (nr. 142); Müslim, Hayz 122 (nr. 375)','Girmeden önce söylenir.'),
  ('غُفْرَانَكَ','(Allahım!) Bağışlamanı dilerim.',1,'Ebû Dâvûd, Tahâret 17 (nr. 30); Tirmizî, Tahâret 5 (nr. 7)','Çıkınca söylenir.'),
 ]),
 ('Abdest alırken ve sonrasında', [
  ('بِسْمِ اللَّهِ','Allah’ın adıyla.',1,'Ebû Dâvûd, Tahâret 48 (nr. 101)','Abdeste başlarken söylenir.'),
  ('أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ','Allah’tan başka ilâh olmadığına şahitlik ederim; O tektir, ortağı yoktur. Muhammed’in O’nun kulu ve elçisi olduğuna da şahitlik ederim.',1,'Müslim, Tahâret 17 (nr. 234)','Abdestini güzelce alıp bunu söyleyene cennetin sekiz kapısı açılır, dilediğinden girer.'),
  ('اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ، وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ','Allahım! Beni çok tövbe edenlerden ve temizlenenlerden eyle.',1,'Tirmizî, Tahâret 41 (nr. 55)',''),
  ('سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ','Allahım! Seni hamd ile tesbih ederim. Senden başka ilâh olmadığına şahitlik ederim. Senden bağışlanma diler, sana tövbe ederim.',1,'Nesâî, Amelü’l-yevm ve’l-leyle, nr. 81',''),
 ]),
 ('Evden çıkarken', [
  ('بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ','Allah’ın adıyla (çıkarım). Allah’a tevekkül ettim. Güç ve kuvvet ancak Allah’ındır.',1,'Ebû Dâvûd, Edeb 103 (nr. 5095); Tirmizî, Daavât 34 (nr. 3426)','Ona: “Doğru yola iletildin, ihtiyacın görüldü, korundun” denir ve şeytan ondan uzaklaşır.'),
  ('اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ','Allahım! Sapmaktan veya saptırılmaktan, kaymaktan veya kaydırılmaktan, zulmetmekten veya zulme uğramaktan, cahillik etmekten veya bana cahillik edilmesinden sana sığınırım.',1,'Ebû Dâvûd, Edeb 103 (nr. 5094); Tirmizî, Daavât 34 (nr. 3427)',''),
 ]),
 ('Eve girerken', [
  ('بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَىٰ رَبِّنَا تَوَكَّلْنَا','Allah’ın adıyla girdik, Allah’ın adıyla çıktık ve Rabbimize tevekkül ettik.',1,'Ebû Dâvûd, Edeb 103 (nr. 5096)','Sonra ev halkına selâm verir.'),
 ]),
 ('Aynaya bakınca', [
  ('اللَّهُمَّ أَنْتَ حَسَّنْتَ خَلْقِي فَحَسِّنْ خُلُقِي','Allahım! Yaratılışımı güzel yaptın, ahlâkımı da güzelleştir.',1,'Ahmed b. Hanbel, el-Müsned, I, 403; VI, 68',''),
 ]),
]),
('🕌 Mescit, ezan ve namaz', [
 ('Mescide giderken', [
  ('اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَفِي سَمْعِي نُورًا، وَفِي بَصَرِي نُورًا، وَمِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ شِمَالِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَمِنْ خَلْفِي نُورًا، وَاجْعَلْ فِي نَفْسِي نُورًا، وَأَعْظِمْ لِي نُورًا','Allahım! Kalbime nur, dilime nur, kulağıma nur, gözüme nur koy; üstüme nur, altıma nur, sağıma nur, soluma nur, önüme nur, arkama nur ver. Nefsime nur koy, nurumu büyüt.',1,'Buhârî, Daavât 10 (nr. 6316); Müslim, Müsâfirîn 181 (nr. 763)',''),
 ]),
 ('Mescide girerken', [
  ('أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ','Kovulmuş şeytandan; büyük Allah’a, O’nun kerîm zâtına ve ezelî saltanatına sığınırım.',1,'Ebû Dâvûd, Salât 18 (nr. 466)','Bunu söyleyene şeytan: “Bu gün boyu benden korundu” der.'),
  ('بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَىٰ رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ','Allah’ın adıyla; salât ve selâm Allah’ın Resûlüne olsun. Allahım! Bana rahmetinin kapılarını aç.',1,'Müslim, Müsâfirîn 68 (nr. 713); İbn Mâce, Mesâcid 13 (nr. 771)','Sağ ayakla girilir.'),
 ]),
 ('Mescitten çıkarken', [
  ('بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَىٰ رَسُولِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ','Allah’ın adıyla; salât ve selâm Allah’ın Resûlüne olsun. Allahım! Senden lütfunu isterim.',1,'Müslim, Müsâfirîn 68 (nr. 713); İbn Mâce, Mesâcid 13 (nr. 773)','Sol ayakla çıkılır.'),
 ]),
 ('Ezanı işitince ve ezandan sonra', [
  ('(يُقَالُ مِثْلَ مَا يَقُولُ الْمُؤَذِّنُ) … لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ','Müezzinin söylediği aynen tekrarlanır; “Hayya ale’s-salâh” ve “Hayya ale’l-felâh”ta “Lâ havle ve lâ kuvvete illâ billâh” denir.',1,'Buhârî, Ezân 7 (nr. 611); Müslim, Salât 12 (nr. 385)',''),
  ('وَأَنَا أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللَّهِ رَبًّا، وَبِمُحَمَّدٍ رَسُولًا، وَبِالْإِسْلَامِ دِينًا','Ben de şahitlik ederim ki Allah’tan başka ilâh yoktur; O tektir, ortağı yoktur. Muhammed O’nun kulu ve elçisidir. Rab olarak Allah’tan, elçi olarak Muhammed’den, din olarak İslâm’dan razı oldum.',1,'Müslim, Salât 13 (nr. 386)','Müezzinin şehadetlerinden sonra söyleyenin günahları bağışlanır.'),
  ('اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ … اللَّهُمَّ رَبَّ هَٰذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ','(Ezandan sonra salavat getirilir, sonra:) Allahım! Ey bu eksiksiz davetin ve kılınacak namazın Rabbi! Muhammed’e vesîleyi ve fazileti ver; onu vaad ettiğin Makām-ı Mahmûd’a ulaştır.',1,'Buhârî, Ezân 8 (nr. 614); Müslim, Salât 11 (nr. 384)','Bunu söyleyene kıyamet günü şefaatim helâl olur.'),
  ('(الدُّعَاءُ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ)','Ezan ile kamet arasında dilediği duayı yapar.',1,'Tirmizî, Salât 44 (nr. 212); Ebû Dâvûd, Salât 35 (nr. 521)','Ezan ile kamet arasındaki dua geri çevrilmez.'),
 ]),
 ('Namaza başlarken (istiftâh)', [
  ('سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَىٰ جَدُّكَ، وَلَا إِلَٰهَ غَيْرُكَ','Allahım! Seni hamd ile tesbih ederim. İsmin mübarektir, şanın yücedir; senden başka ilâh yoktur.',1,'Ebû Dâvûd, Salât 122 (nr. 775); Tirmizî, Salât 65 (nr. 243)','Sübhâneke duası.'),
  ('اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْ خَطَايَايَ بِالثَّلْجِ وَالْمَاءِ وَالْبَرَدِ','Allahım! Doğu ile batıyı birbirinden uzaklaştırdığın gibi benimle günahlarım arasını uzaklaştır. Allahım! Beyaz elbisenin kirden temizlendiği gibi beni günahlarımdan temizle. Allahım! Günahlarımı kar, su ve dolu ile yıka.',1,'Buhârî, Ezân 89 (nr. 744); Müslim, Mesâcid 147 (nr. 598)',''),
 ]),
 ('Rükûda', [
  ('سُبْحَانَ رَبِّيَ الْعَظِيمِ','Yüce Rabbimi tesbih ederim.',3,'Ebû Dâvûd, Salât 151 (nr. 870); Tirmizî, Salât 79 (nr. 262)',''),
  ('سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ','Meleklerin ve Ruh’un (Cebrâil’in) Rabbi her türlü noksandan münezzeh ve mukaddestir.',1,'Müslim, Salât 223 (nr. 487)',''),
 ]),
 ('Rükûdan doğrulurken', [
  ('سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ','Allah kendisine hamd edeni işitir.',1,'Buhârî, Ezân 124 (nr. 789)',''),
  ('رَبَّنَا وَلَكَ الْحَمْدُ، حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ','Rabbimiz! Hamd sanadır; çok, temiz ve bereketli bir hamd.',1,'Buhârî, Ezân 126 (nr. 799)','Otuz küsur melek bunu ilk önce yazmak için yarıştı.'),
 ]),
 ('Secdede', [
  ('سُبْحَانَ رَبِّيَ الْأَعْلَىٰ','En yüce Rabbimi tesbih ederim.',3,'Ebû Dâvûd, Salât 151 (nr. 870); Tirmizî, Salât 82 (nr. 262)',''),
  ('اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ: دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ','Allahım! Günahlarımın hepsini bağışla: küçüğünü ve büyüğünü, ilkini ve sonunu, açığını ve gizlisini.',1,'Müslim, Salât 216 (nr. 483)','Kulun Rabbine en yakın olduğu an secde hâlidir; orada duayı çoğaltın (Müslim, nr. 482).'),
 ]),
 ('İki secde arasında', [
  ('رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي','Rabbim, beni bağışla; Rabbim, beni bağışla.',1,'Ebû Dâvûd, Salât 152 (nr. 874); İbn Mâce, İkâme 23 (nr. 897)',''),
  ('اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَاجْبُرْنِي، وَعَافِنِي، وَارْزُقْنِي، وَارْفَعْنِي','Allahım! Beni bağışla, bana merhamet et, beni doğru yola ilet, eksiğimi gider, bana âfiyet ver, beni rızıklandır ve derecemi yükselt.',1,'Ebû Dâvûd, Salât 145 (nr. 850); Tirmizî, Salât 95 (nr. 284); İbn Mâce, İkâme 23 (nr. 898)',''),
 ]),
 ('Tilâvet secdesinde', [
  ('سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ، فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ','Yüzüm onu yaratan, gücü ve kuvvetiyle kulağını ve gözünü açan Allah’a secde etti. Yaratanların en güzeli olan Allah ne yücedir!',1,'Ebû Dâvûd, Salât 334 (nr. 1414); Tirmizî, Salât 286 (nr. 580); Hâkim, I, 220',''),
 ]),
 ('Teşehhüd (Tahiyyât)', [
  ('التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَىٰ عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ','Her türlü saygı, dualar ve güzellikler Allah’a mahsustur. Ey Peygamber! Allah’ın selâmı, rahmeti ve bereketi senin üzerine olsun. Selâm bizim ve Allah’ın salih kullarının üzerine olsun. Allah’tan başka ilâh olmadığına şahitlik ederim; Muhammed’in O’nun kulu ve elçisi olduğuna da şahitlik ederim.',1,'Buhârî, Ezân 148 (nr. 831); Müslim, Salât 55 (nr. 402)',''),
 ]),
 ('Teşehhüdden sonra salavât', [
  ('اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ','Allahım! İbrâhim’e ve âline salât ettiğin gibi Muhammed’e ve âline de salât et; şüphesiz sen övülmeye lâyıksın, şanı yücesin. Allahım! İbrâhim’e ve âline bereket verdiğin gibi Muhammed’e ve âline de bereket ver; şüphesiz sen övülmeye lâyıksın, şanı yücesin.',1,'Buhârî, Enbiyâ 10 (nr. 3370); Müslim, Salât 66 (nr. 406)','Salli-Bârik duaları.'),
 ]),
 ('Selâmdan önce', [
  ('اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ جَهَنَّمَ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ','Allahım! Kabir azabından, cehennem azabından, hayatın ve ölümün fitnesinden ve Mesîh Deccâl’in fitnesinin şerrinden sana sığınırım.',1,'Buhârî, Cenâiz 87 (nr. 1377); Müslim, Mesâcid 128 (nr. 588)',''),
  ('اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ','Allahım! Ben nefsime çok zulmettim; günahları ancak sen bağışlarsın. Katından bir bağışlama ile beni bağışla ve bana merhamet et. Şüphesiz sen çok bağışlayan, çok merhamet edensin.',1,'Buhârî, Ezân 149 (nr. 834); Müslim, Zikir 48 (nr. 2705)','Resûlullah bunu Hz. Ebû Bekir’e namazında okuması için öğretti.'),
  ('رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ','Rabbimiz! Bize dünyada iyilik ver, âhirette de iyilik ver ve bizi ateş azabından koru. (Bakara 2/201)',1,'Buhârî, Tefsîr (Bakara) 36 (nr. 4522); Müslim, Zikir 26 (nr. 2690)','Resûlullah’ın en çok yaptığı dua.'),
 ]),
 ('Vitir namazında kunut', [
  ('اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَىٰ عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ','Allahım! Hidayet verdiklerinle birlikte beni de hidayete erdir; âfiyet verdiklerinle birlikte bana da âfiyet ver; dost edindiklerinle birlikte beni de dost edin; verdiklerini benim için bereketli kıl; hükmettiğin şeyin şerrinden beni koru. Hükmeden sensin, sana hükmedilemez. Senin dost edindiğin zelil olmaz. Rabbimiz, sen ne yücesin, ne yükseksin!',1,'Ebû Dâvûd, Vitir 5 (nr. 1425); Tirmizî, Vitir 10 (nr. 464)','Resûlullah bunu Hz. Hasan’a öğretti.'),
  ('اللَّهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَغْفِرُكَ وَنَسْتَهْدِيكَ، وَنُؤْمِنُ بِكَ وَنَتُوبُ إِلَيْكَ، وَنَتَوَكَّلُ عَلَيْكَ، وَنُثْنِي عَلَيْكَ الْخَيْرَ كُلَّهُ، نَشْكُرُكَ وَلَا نَكْفُرُكَ، وَنَخْلَعُ وَنَتْرُكُ مَنْ يَفْجُرُكَ. اللَّهُمَّ إِيَّاكَ نَعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعَىٰ وَنَحْفِدُ، نَرْجُو رَحْمَتَكَ، وَنَخْشَىٰ عَذَابَكَ، إِنَّ عَذَابَكَ بِالْكُفَّارِ مُلْحِقٌ','Allahım! Senden yardım ister, bağışlanma diler, hidayet isteriz. Sana inanır, sana tövbe eder, sana dayanırız. Bütün iyiliklerle seni överiz; sana şükreder, nankörlük etmeyiz. Sana karşı geleni bırakır, ondan ayrılırız. Allahım! Yalnız sana kulluk eder, senin için namaz kılar, sana secde ederiz. Sana koşar, sana hizmete can atarız. Rahmetini umar, azabından korkarız. Şüphesiz senin azabın kâfirlere ulaşır.',1,'Beyhakî, es-Sünenü’l-kübrâ, II, 210-211 (Hz. Ömer’den); İbn Ebî Şeybe, el-Musannef, nr. 7027','Hanefîlerin vitirde okuduğu Kunut duaları.'),
  ('سُبْحَانَ الْمَلِكِ الْقُدُّوسِ','Mukaddes olan Melik (Allah) her türlü noksandan uzaktır.',3,'Nesâî, Kıyâmü’l-leyl 51 (nr. 1699); Ebû Dâvûd, Vitir 5 (nr. 1430)','Vitirden selâm verince üç kez söylenir; üçüncüsünde ses uzatılır.'),
 ]),
 ('İstihâre duası', [
  ('اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَٰذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاقْدُرْهُ لِي، وَيَسِّرْهُ لِي، ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَٰذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاصْرِفْهُ عَنِّي، وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ أَرْضِنِي بِهِ','Allahım! İlminle senden hayır isterim, kudretinle güç isterim, büyük lütfundan isterim. Sen güç yetirirsin, ben yetiremem; sen bilirsin, ben bilmem; gaybları bilen sensin. Allahım! Bu iş (adını söyler) dinim, geçimim ve işimin sonu bakımından benim için hayırlı ise onu bana takdir et, kolaylaştır, sonra onu bana bereketli kıl. Eğer bu iş dinim, geçimim ve işimin sonu bakımından benim için şerli ise onu benden, beni de ondan uzaklaştır; hayır nerede ise onu bana takdir et, sonra beni ondan razı kıl.',1,'Buhârî, Teheccüd 25 (nr. 1162)','Bir işe karar vermek isteyen farz olmayan iki rekât namaz kılar, sonra bu duayı okur ve “hâzel-emr” yerinde işini anar.'),
 ]),
 ('Namazdan sonra', [
  ('أَذْكَارُ مَا بَعْدَ السَّلَامِ مِنَ الصَّلَاةِ','Namazdan sonraki istiğfar, tesbihat ve dualar üstteki “🕌 Namazdan sonra” sekmesinde sayaçlı olarak yer alır.',1,'Müslim, Mesâcid 135-146 (nr. 591-597)',''),
 ]),
]),
]
